import{_ as e,o as n,c as r,ah as a}from"./chunks/framework.C-FRNfAJ.js";const l=JSON.parse('{"title":"Technology partnerships","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/activites/partenariats.md","filePath":"src/en/guide/activites/partenariats.md"}'),o={name:"en/guide/activites/partenariats.md"};function s(i,t,h,g,p,c){return n(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="technology-partnerships" tabindex="-1">Technology partnerships <a class="header-anchor" href="#technology-partnerships" aria-label="Permalink to &quot;Technology partnerships&quot;">​</a></h1><p>A technology partnership integrates an organization&#39;s tool, platform or certification into one or more programs. It is <strong>free</strong>, in exchange for <strong>visibility</strong> to learners.</p><p>The <strong>Partnerships Officer</strong> and the Administrator manage them, in <strong>Activities → Technology partnerships</strong>.</p><h2 id="creating-a-partnership" tabindex="-1">Creating a partnership <a class="header-anchor" href="#creating-a-partnership" aria-label="Permalink to &quot;Creating a partnership&quot;">​</a></h2><p><strong>New partnership</strong>: the partnership is born <strong>Under negotiation</strong>. Enter:</p><ul><li>the <strong>partner organisation</strong> and the <strong>solution name</strong>;</li><li>the <strong>nature</strong>: pedagogical integration, certification or tool supply;</li><li>the <strong>programs concerned</strong> (at least one);</li><li>the partner&#39;s <strong>signatory</strong>, with their name and e-mail;</li><li>the <strong>planned end</strong>, optional.</li></ul><p>A partnership can be edited, or deleted, <strong>until it is signed</strong>. Editing a partnership whose contract is already sent withdraws that sending: the contract must be sent again.</p><h2 id="getting-the-contract-signed" tabindex="-1">Getting the contract signed <a class="header-anchor" href="#getting-the-contract-signed" aria-label="Permalink to &quot;Getting the contract signed&quot;">​</a></h2><p><strong>Send the contract</strong> sends the signatory a link by e-mail, valid <strong>7 days</strong>. They read the contract to the end, accept it on behalf of their organization and sign it with a <strong>code</strong> received at the same address, <strong>with no Kura account</strong>. <strong>Send the contract again</strong> issues a new link.</p><p>Then edPage group <strong>counter-signs</strong>: automatically (by default) or, depending on the Administrator&#39;s setting, by a Partnerships Officer with <strong>Counter-sign</strong>.</p><p>On counter-signature, the contract receives its reference <code>CONVP-NB-YYYY-XXX</code> and its sealed PDF, sent to the contact and to the Officers. The partnership becomes <strong>Active</strong>: the partner, solution, nature and programs are then <strong>frozen</strong>.</p><h2 id="visibility" tabindex="-1">Visibility <a class="header-anchor" href="#visibility" aria-label="Permalink to &quot;Visibility&quot;">​</a></h2><p>The partnership&#39;s <strong>visibility</strong> stays editable: a presentation (500 characters at most), the partner&#39;s website, a logo (PNG, JPEG or WebP, 1 MB at most). A preview is displayed.</p><p>An active partnership appears:</p><ul><li>on the page of <strong>each of its programs</strong> on the NextBoxx website;</li><li>in a &quot;<strong>Partners</strong>&quot; block of the Sève course summary of the cohorts concerned, updated every hour;</li><li>for learners, under <strong>Partner tools</strong> in their space.</li></ul><h2 id="the-end-of-a-partnership" tabindex="-1">The end of a partnership <a class="header-anchor" href="#the-end-of-a-partnership" aria-label="Permalink to &quot;The end of a partnership&quot;">​</a></h2><p>The partnership <strong>ends the day after its end date</strong>, set at creation or later. It becomes <strong>Ended</strong> and the website no longer shows it.</p><p>A cohort of a program concerned <strong>keeps the partner until its own end</strong>, in Sève and in the learners&#39; space, if it has started, or if one of its enrolments was signed, at the latest on the partnership&#39;s end date.</p>',18)])])}const u=e(o,[["render",s]]);export{l as __pageData,u as default};
